const rank = p => ({ P0: 0, P1: 1, P2: 2 }[p] ?? 3);
const CODE = /\b(fix|build|re-?run|e2e|ci\b|refactor|deploy|migrat)/i;
const now = Date.now();
const free = r => r.status === 'todo' || (r.status === 'running' && (!r.lease_until || new Date(r.lease_until).getTime() < now));
// Role playbooks (MIT msitarzewski/agency-agents, vendored unmodified)
const V = '00-hq/vendor/agency-agents/';
const PB = { Scout: 'product/product-trend-researcher.md', Kavi: 'marketing/marketing-content-creator.md', Adi: 'sales/sales-offer-lead-gen-strategist.md', Lens: 'design/design-brand-guardian.md', Forge: 'engineering/engineering-backend-architect.md', Vigil: 'testing/testing-reality-checker.md', Guard: 'support/support-legal-compliance-checker.md', Deal: 'marketing/marketing-growth-hacker.md', Echo: 'research/research-synthesist.md', Kalpa: 'specialized/specialized-chief-of-staff.md', Customer: 'product/product-feedback-synthesizer.md', 'Competitor Watch': 'specialized/business-strategist.md' };
const rows = $input.all().map(i => i.json).filter(r => r && r.id && free(r) && !(/^(forge|probe)$/i.test(String(r.owner_agent)) && CODE.test(String(r.title))));
if (!rows.length) return [];
rows.sort((a, b) => rank(a.priority) - rank(b.priority) || String(a.due_on || '9').localeCompare(String(b.due_on || '9')) || a.id - b.id);
const t = rows[0];
const agent = t.owner_agent || 'Kalpa';
const retry = t.status === 'running' ? 'RETRY after an interrupted run. ' : '';
return [{ json: { id: t.id, title: t.title, owner_agent: agent, stream: t.stream || 'HQ', priority: t.priority, needs_ceo: !!t.needs_ceo, notes: retry + (t.output_summary || ''), playbook: PB[agent] ? V + PB[agent] : '' } }];

