const W = [['HQ','Kalpa HQ (the company)'],['b5','Telugu Deals (money sprint track 1)'],['b4','Tab Lifeboat (money sprint track 2)'],['b1','BotBhai (money sprint track 3)']];
const day = $now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy');
const due = $now.setZone('Asia/Kolkata').toISODate();
const rows = W.map(([s, n]) => ({ json: { title: `(Council ${day}) ROAST ROOM for ${n}: first read_kalpa_file('00-hq/agents/council/ROAST-ROOM.md') and follow it exactly, then read_kalpa_file('00-hq/ROADMAP.md') only for the 'Money sprint' block, then that world's README. Today's decision: what is the ONE action this week that brings the first real rupee closest (Deals: first Rs 1,000 commission; Tab Lifeboat: listed with Pro on sale; BotBhai: 1 signed pilot), and what should we STOP doing? Use the output shape in the file, under 400 words.`, owner_agent: 'Council', stream: s, status: 'todo', priority: 'P0', due_on: due, needs_ceo: false, created_by: 'Council Daily' } }));
if ($now.setZone('Asia/Kolkata').weekday === 1) {
  const C = [['b1','BotBhai: WhatsApp/website booking assistant for salons, gyms, coaching (India)','P0'],['b4','Tab Lifeboat: browser tab saver extension with a Pro plan','P0'],['b5','Telugu Deals: affiliate deals channel + money tools for Telugu speakers','P0'],['b3','Exam & Money Kits: Google Sheets kits for GATE/tax','P2'],['b2','JobCard: job-card + invoice app for AC technicians','P2'],['b6','Ledger Peaks: AI/LLM cost tracking in rupees for software teams','P2'],['b7','Trading Lab: paper-trading research only, never sold','P2'],['HQ','Kalpa Labs: one-founder AI company','P1']];
  for (const [s, n, p] of C) rows.push({ json: { title: `(Max 450 words) COMPETITOR WATCH ${day} for ${n}. BUSINESS ONLY: do not study or describe competitors' app screens, UI or login flows (Kalpa designs its own warm Kalpavruksha look). Find the 5 best companies in the world doing this today (real paying customers), using their own websites, pricing pages, public reviews and open-source repos only. For each: what customers actually pay for (plan, price, the outcome that sells), how they find and keep customers, their top 3 customer complaints. Then: 3 concrete things Kalpa should build or offer next to solve those complaints better, each with an MIT/Apache open-source repo or free tool that helps (licence checked). Read the world's README first with read_kalpa_file. Cite every claim.`, owner_agent: 'Competitor Watch', stream: s, status: 'todo', priority: p, due_on: due, needs_ceo: false, created_by: 'Council Daily' } });
}
return rows;
